create trigger Annotation_CascadeUpdate 
after update on Annotation
for each row 
begin 
update EntityLink set SourceID = new.ID where SourceID = old.ID;
update EntityLink set TargetID = new.ID where TargetID = old.ID;
end;

create trigger Category_CascadeUpdate 
after update on Category 
for each row 
begin 
update CategoryCategory set ParentCategoryID = new.ID where ParentCategoryID = old.ID;
