update EntityLink set SourceID = new.ID where SourceID = old.ID;
update EntityLink set TargetID = new.ID where TargetID = old.ID;
update KnowledgeItemCategory set CategoryID = new.ID where CategoryID = old.ID;
update ReferenceCategory set CategoryID = new.ID where CategoryID = old.ID;
end;

